def adj(a,b,c,d): return abs(b-a)==1 and abs(c-d)==1

def f(g):
    h,w=len(g),len(g[0])
    out=[r[:] for r in g]
    cells={}
    for i in range(h):
        for j in range(w):
            v=g[i][j]
            if v!=g[0][0]: cells.setdefault(v,set()).add((i,j))
    for v,s in cells.items():
        # group into diagonal chains via adjacency
        used=set(); groups=[]
        for p in sorted(s):
            if p in used: continue
            st=[p]; grp={p}
            while st:
                q=st.pop()
                for r2,c2 in s:
                    if (r2,c2) in used or (r2,c2) in grp: continue
                    if adj(q[0],q[1],r2,c2): st.append((r2,c2)); grp.add((r2,c2))
            used|=grp; groups.append(grp)
        for grp in groups:
            if len(grp)<2: continue
            drs=[b[0]-a[0] for a,b in zip(sorted(grp),sorted(grp, key=lambda x:(x[0]+x[1]))) ]
            # determine direction sign from the group extent
            pts=sorted(grp)
            da=pts[1][0]-pts[0][0]; db=pts[1][1]-pts[0][1]
            if da==0 or db==0: continue
            if da*db<0: continue  # anti-diagonal pairs only? try: extend both ways
            # for main-diagonal (da,db same sign), extend both ways; for anti-diag (opposite sign), also both
            # decide: extend outward from both ends
            import math
            def ext(p,dx,dy):
                p=list(p)
                while True:
                    p[0]+=dx;p[1]+=dy
                    if not(0<=p[0]<h and 0<=p[1]<w): break
                    if out[p[0]][p[1]]==g[0][0] or out[p[0]][p[1]]==v: out[p[0]][p[1]]=v
                    elif out[p[0]][p[1]]!=g[0][0]: break
            # unit step
            sx=sy=0
            if da==db: sx,sy=1,1
            else: sx,sy=1,-1
            e1,e2=pts[0],pts[-1]
            ext(e1,-sx,-sy); ext(e2,sx,sy)
    return out

