def f(g):
    bg=g[0][0]; h,w=len(g),len(g[0])
    out=[r[:] for r in g]
    # collect colors per anti-diagonal sum s=i+j
    from collections import defaultdict
    d=defaultdict(list)
    for i in range(h):
        for j in range(w):
            v=g[i][j]
            if v!=bg: d[i+j].append((i,j,v))
    for s,pairs in list(d.items()):
        seen=set()
        while True:
            st=pairs[:1]; grp={st[0]}
            while len(grp)<2 and st:
                q=st.pop(); nq=next(p for p in pairs if p not in grp and abs(p[0]-q[0])==abs(p[1]-q[1]))
                if not nq or (nq[0]-q[0])*-1>0: pass
            # simpler: DFS with adjacency along diagonal only
            seen.add(st[0]); chain=[st[0]]
            frontier=[st[0]]
            while frontier:
                q=frontier.pop()
                for cand in pairs:
                    if cand in chain or cand in seen: continue
                    if abs(cand[0]-q[0])!=abs(cand[1]-q[1]): continue
                    chain.append(cand); seen.add(cand)
                if chain[-1]!=q: frontier=[c for c in pairs if c not in seen and abs(c[0]-chain[-1][0])==abs(c[1]-chain[-1][1])]
            if len(chain)>=2:
                v=chain[0][2]
                for k in range(1,len(chain)):
                    a,b=chain[k-1],chain[k]
                    if (b[0]-a[0],b[1]-a[1]) not in [(1,-1),(-1,1)]: pass
                # walk outward
                for dx,dy in ((1,-1),(-1,1)):
                    p=chain[-1] if dx==1 else chain[0]
                    for _ in range(400):
                        n=(p[0]+dx,p[1]+dy)
                        if not(0<=n[0]<h and 0<=n[1]<w): break
                        if g[n[0]][n[1]]!=bg: break
                        out[n[0]][n[1]]=v
            else:
                seen.discard(st[0]); pairs=[p for p in pairs if p not in seen]
    return out
