def f(g):
    bg=g[0][0]; h,w=len(g),len(g[0])
    out=[r[:] for r in g]
    # anti-diagonal chains: cells with same sum s=i+j, adjacent along it (|di|=|dj|=1)
    from collections import defaultdict,deque
    d=defaultdict(list)
    for i in range(h):
        for j in range(w):
            if g[i][j]!=bg: d[i+j].append((i,j,g[i][j]))
    used=set()
    for s in list(d):
        lst=d[s]
        if len(lst)<2: continue
        dset=set(lst)
        while True:
            head=None
            for p in lst:
                nxt=[q for q in lst if q not in {p} and abs(q[0]-p[0])==abs(q[1]-p[1])]
                if nxt: head=p; break
            if not head: continue
            chain=deque([head])
            while chain:
                q=chain[-1]
                for c in lst:
                    if c not in set(chain) and abs(c[0]-q[0])==abs(c[1]-q[1]):
                        chain.append(c); dset.add(c)
            if len(chain)<2: 
                used-=dset; dset=set(lst); continue
            seen=set(map(tuple,list(chain)))
            v=g[list(chain)[0][0]][list(chain)[0][1]]
            p_end=(list(chain)[-1]); p_st=list(chain)[0]
            dx,dy=(1,-1)*(-1)  # unused
            for sx,sy in ((1,-1),(-1,1)):
                p=(p_end[0]+sx,p_end[1]+sy)
                while 0<=p[0]<h and 0<=p[1]<w and g[p[0]][p[1]]==bg:
                    out[p[0]][p[1]]=v; p=(p[0]+sx,p[1]+sy)
                p=(p_st[0]-sx,p_st[1]-sy)
                while 0<=p[0]<h and 0<=p[1]<w and g[p[0]][p[1]]==bg:
                    out[p[0]][p[1]]=v; p=(p[0]-sx,p[1]-sy)
            used|=seen; dset={q for q in dset if q not in seen}
    return out

