def f(g):
    H,W=len(g),len(g[0])
    cnt=Counter(x for row in g for x in row)
    bg=cnt.most_common(1)[0][0]
    out=[row[:] for row in g]
    cols=[c for c in set(x for row in g for x in row)-{bg}]
    for col in cols:
        cells=[(r,c) for r in range(H) for c in range(W) if g[r][c]==col]
        if len(cells)<2: continue
        found=False
        for dr,dc in [(1,1),(1,-1),(-1,1),(-1,-1)]:
            # largest prefix consecutive along dir
            d=sorted(cells,key=lambda p:(p[0]*dr+p[1]*dc))
            k=0
            while k+1<len(d) and (d[k+1][0]-d[k][0])==dr and (d[k+1][1]-d[k][1])==dc:
                k+=1
            if k>=1:
                e,d2=d[k],d[k-1]
                ext=[]
                n=(e[0]+dr,e[1]+dc)
                while 0<=n[0]<H and 0<=n[1]<W:
                    ext.append(n); e=n; n=(e[0]+dr,e[1]+dc)
                m=(d2[0]-dr,d2[1]-dc)
                while 0<=m[0]<H and 0<=m[1]<W:
                    ext.append(m); d2=m; m=(d2[0]-dr,d2[1]-dc)
                for rr,cc in ext:
                    if out[rr][cc]==col or out[rr][cc]==bg:
                        out[rr][cc]=col
                found=True; break
        if found: break
    return out

