def f(gi, out=None):
    H,W=len(gi),len(gi[0])
    bg=Counter(x for row in gi for x in row).most_common(1)[0][0]
    fig=[(r,c) for r in range(H) for c in range(W) if gi[r][c]!=bg]
    bycol=dd(list)
    for r,c in fig: bycol[gi[r][c]].append((r,c))
    for col,cells in sorted(bycol.items()):
        dirs=[]
        for a,b in [(1,1),(1,-1),(-1,1),(-1,-1)]:
            d=sorted(cells,key=lambda p:(p[0]*a+p[1]*b))
            if len(d)<2: continue
            if all((d[k+1][0]-d[k][0],d[k+1][1]-d[k][1])==(a,b) for k in range(len(d)-1)): dirs.append((a,b))
        if not dirs: continue
        # pick the direction; ambiguous cases resolved per-pair below; try both and pick which matches later
        for dr,dc in dirs:
            e=max(cells,key=lambda p:(p[0]*dr+p[1]*dc)); s=min(cells,key=lambda p:(p[0]*dr+p[1]*dc))
            ext=[]
            n=(e[0]+dr,e[1]+dc)
            while 0<=n[0]<H and 0<=n[1]<W and gi[n[0]][n[1]]==bg:
                ext.append(n); n=(n[0]+dr,n[1]+dc)
            m=(s[0]-dr,s[1]-dc)
            while 0<=m[0]<H and 0<=m[1]<W and gi[m[0]][m[1]]==bg:
                ext.append(m); m=(m[0]-dr,m[1]-dc)
            if ext:
                if out is None:
                    return dict(col=col,dir=(dr,dc),ext=ext,cells=cells)
                else:
                    for rr,cc in ext: out[rr][cc]=col
    return None

