    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
from collections import Counter, defaultdict as dd

def f(g):
    H,W=len(g),len(g[0])
    bg=Counter(x for row in g for x in row).most_common(1)[0][0]
    fig=[(r,c) for r in range(H) for c in range(W) if g[r][c]!=bg]
    bycol={ }
    for r,c in fig: bycol.setdefault(g[r][c],[]).append((r,c))
    out=[row[:] for row in g]
    for col,cells in sorted(bycol.items(),key=str):
        # find all maximal consecutive diagonal runs of same color length>=2
        for a,b in [(1,1),(1,-1),(-1,1),(-1,-1)]:
            d=sorted(cells,key=lambda p:(p[0]*a+p[1]*b))
            runs=[]; cur=[d[0]]
            for k in range(1,len(d)):
                if (d[k][0]-cur[-1][0],d[k][1]-cur[-1][1])==(a,b): cur.append(d[k])
                else:
                    if len(cur)>=2: runs.append(cur)
                    cur=[d[k]]
            if len(cur)>=2: runs.append(cur)
            for run in runs:
                e=run[-1]; s=run[0]
                n=(e[0]+a,e[1]+b)
                while 0<=n[0]<H and 0<=n[1]<W and g[n[0]][n[1]]==bg:
                    out[n[0]][n[1]]=col; n=(n[0]+a,n[1]+b)
                m=(s[0]-a,s[1]-b)
                while 0<=m[0]<H and 0<=m[1]<W and g[m[0]][m[1]]==bg:
                    out[m[0]][m[1]]=col; m=(m[0]-a,m[1]-b)
    return out

for i in [4,5,6,7,8]:
    print(i, f(G[f'Demo pair {i} input'])==G[f'Demo pair {i} output'])
print(json.dumps(f(G['Test input'])))

