from collections import Counter
def runs_of(g):
    H,W=len(g),len(g[0])
    bg=Counter(x for row in g for x in row).most_common(1)[0][0]
    out={}
    for r in range(H):
        for c in range(W):
            if g[r][c]!=bg:
                cc=g[r][c]
                for a,b in [(1,1),(1,-1),(-1,1),(-1,-1)]:
                    cur=[]; rr,c2=r,c
                    while 0<=rr<H and 0<=c2<W and g[rr][c2]==cc:
                        cur.append((rr,c2)); rr+=a; c2+=b
                    if len(cur)>=2:
                        out.setdefault(cc,[]).append(set(cur))
    # unique lines
    uniq={};
    for col,rlist in out.items():
        seen=set()
        uniq[col]=[]
        for run in rlist:
            if run not in seen:
                seen.add(frozenset(run)); uniq[col].append(sorted(run))
    return uniq
def solve(g):
    H,W=len(g),len(g[0])
    bg=Counter(x for row in g for x in row).most_common(1)[0][0]
    fig=[(r,c) for r in range(H) for c in range(W) if g[r][c]!=bg]
    cen=(sum(p[0] for p in fig)/len(fig), sum(p[1] for p in fig)/len(fig))
    res=[]
    for col,runlist in runs_of(g).items():
        for run in runlist:
            cr=sum(p[0] for p in run)/len(run); cc2=sum(p[1] for p in run)/len(run)
            dr=dcl=run[-1][0]-run[0][0], run[-1][1]-run[0][1]
            L=dr[0]*dr[0]+dcl[0]*dcl[0]
            v=(dr[0]/math.sqrt(L), dcl[0]/math.sqrt(L))
            t=(cen[0]-cr)*v[0]+(cen[1]-cc2)*v[1]
            if t>=0:
                nxt=(run[0][0]-dr[0], run[0][1]-dcl[0]); dg=(-dr[0],-dcl[0])
            else:
                nxt=(run[-1][0]+dr[0], run[-1][1]+dcl[0]); dg=(dr[0],dcl[0])
            while 0<=nxt[0]<H and 0<=nxt[1]<W and g[nxt[0]][nxt[1]]==bg:
                res.append((col,nxt[0],nxt[1])); nxt=(nxt[0]+dg[0],nxt[1]+dg[1])
    return res
def apply(g, items):
    out=[row[:] for row in g]
    for col,r,c in items:
        out[r][c]=col
    return out
